/**
 * Maintains a small continuation-aware archive.
 * States are separated by blank parity and previous move axis, then retained
 * by structural score so non-equivalent transport continuations survive beam
 * pruning even when an identical board was reached by a shorter path.
 */
struct ContinuationArchive {
    static constexpr int CLASS_COUNT = 8;
    static constexpr int PER_CLASS = 6;
    std::array<std::vector<BeamState>, CLASS_COUNT> states;

    int class_id(const BeamState& state) const {
        const int color = (state.board.empty_r + state.board.empty_c) & 1;
        int axis = 2;
        if (state.prev_move_direction_idx >= 0) {
            axis = state.prev_move_direction_idx & 1;
        }
        return color * 4 + axis;
    }

    bool better(const BeamState& a, const BeamState& b) const {
        return a.beam_score_val > b.beam_score_val ||
               (a.beam_score_val == b.beam_score_val &&
                a.k_beam_moves < b.k_beam_moves);
    }

    void add(const BeamState& state) {
        std::vector<BeamState>& bucket = states[class_id(state)];
        for (const BeamState& old : bucket) {
            if (old.board.zobrist_hash_value == state.board.zobrist_hash_value &&
                old.prev_move_direction_idx == state.prev_move_direction_idx) {
                return;
            }
        }
        bucket.push_back(state);
        std::sort(bucket.begin(), bucket.end(),
                  [this](const BeamState& a, const BeamState& b) {
                      return better(a, b);
                  });
        if (bucket.size() > PER_CLASS) bucket.resize(PER_CLASS);
    }

    void seed(std::vector<BeamState>& beam, int limit) const {
        std::vector<BeamState> all;
        for (const auto& bucket : states) {
            for (const BeamState& state : bucket) all.push_back(state);
        }
        std::sort(all.begin(), all.end(),
                  [this](const BeamState& a, const BeamState& b) {
                      return better(a, b);
                  });
        std::unordered_set<uint64_t> used;
        for (const BeamState& state : all) {
            if (static_cast<int>(beam.size()) >= limit) break;
            uint64_t key = state.board.zobrist_hash_value ^
                           (static_cast<uint64_t>(
                               state.prev_move_direction_idx + 2) << 56);
            if (used.insert(key).second) beam.push_back(state);
        }
    }
};

